namespace {
// FSpatialHashRuntimeGrid's operator==/!= are not exported; compare through reflection.
bool SameGrid(const FSpatialHashRuntimeGrid& A,const FSpatialHashRuntimeGrid& B) { for(TFieldIterator<FProperty> It(FSpatialHashRuntimeGrid::StaticStruct());It;++It) if(!It->Identical_InContainer(&A,&B,0,PPF_None)) return false; return true; }
bool SameGrids(const TArray<FSpatialHashRuntimeGrid>& A,const TArray<FSpatialHashRuntimeGrid>& B) { if(A.Num()!=B.Num()) return false; for(int32 I=0;I<A.Num();++I) if(!SameGrid(A[I],B[I])) return false; return true; }
}

#if WITH_EDITORONLY_DATA
// The engine declares these operators but does not export them from the Engine module; define them here per-field.
bool FSpatialHashRuntimeGrid::operator==(const FSpatialHashRuntimeGrid& Other) const { return SameGrid(*this,Other); }
bool FSpatialHashRuntimeGrid::operator!=(const FSpatialHashRuntimeGrid& Other) const { return !SameGrid(*this,Other); }
#endif
namespace { void RequireSafeRuntimeGridToken(const FString& Text)
{
 if(Text.IsEmpty() || FName(*Text).IsNone()) return;
 if(Text.Len()>256) throw std::runtime_error("Runtime grid token exceeds256 characters");
 for(TCHAR Ch:Text) if(Ch<=32 || Ch==127) throw std::runtime_error("Runtime grid token contains whitespace/control character");
 TArray<FString> Parts; Text.ParseIntoArray(Parts,TEXT(":"),false);
 if(Parts.Num()<1 || Parts.Num()>2 || Parts[0].IsEmpty() || (Parts.Num()==2 && Parts[1].IsEmpty())) throw std::runtime_error("Runtime grid requires main token and optional nonempty HLOD token");
 TArray<FString> Main; Parts[0].ParseIntoArray(Main,TEXT("."),false);
 if(Main.IsEmpty()) throw std::runtime_error("Runtime grid main token required");
 for(const auto& Token:Main) if(Token.IsEmpty()) throw std::runtime_error("Runtime grid main dotted tokens cannot be empty");
} }
